#!/usr/bin/env node
'use strict';
// Writes one command per built-in style (skills/<style>/SKILL.md) from styles/styles.json.
// Run after editing styles.json. `--check` exits 1 when a generated file is out of date (used in CI).
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const styles = JSON.parse(fs.readFileSync(path.join(ROOT, 'styles', 'styles.json'), 'utf8'));
const CORE = ['make', 'shoot', 'render', 'styles', 'mix', 'restyle', 'new-style'];

// Style commands are typed by the user, so they are hidden from the model (no description in every session's context).
// Natural-language requests go through the one visible skill, make.
function skill(id, s) {
  return `---
name: ${id}
description: "Video Creator: ${s.name}. ${s.tagline}"
argument-hint: "<idea> [--shorts|--youtube|--square|--feed] [--seconds 15|30|60]"
disable-model-invocation: true
---

<!-- Generated by scripts/gen-skills.js from styles/styles.json. Edit those, then run: node scripts/gen-skills.js -->

**Idea:** $ARGUMENTS

Read \`\${CLAUDE_PLUGIN_ROOT}/skills/make/SKILL.md\` and follow it with the style \`${id}\` already chosen.
`;
}

function main(check) {
  const stale = [];
  for (const [id, s] of Object.entries(styles)) {
    if (CORE.includes(id)) throw new Error(`style id "${id}" clashes with a core command`);
    const file = path.join(ROOT, 'skills', id, 'SKILL.md');
    const text = skill(id, s);
    const now = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
    if (now === text) continue;
    if (check) stale.push(path.relative(ROOT, file));
    else { fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, text); }
  }
  const known = new Set([...CORE, ...Object.keys(styles)]);
  const extra = fs.readdirSync(path.join(ROOT, 'skills')).filter((d) => !known.has(d));
  if (extra.length) stale.push(...extra.map((d) => `skills/${d} (no such style)`));
  if (stale.length) { process.stderr.write(`out of date:\n  ${stale.join('\n  ')}\nrun: node plugins/video-creator/scripts/gen-skills.js\n`); return 1; }
  return 0;
}

if (require.main === module) process.exitCode = main(process.argv.includes('--check'));
module.exports = { skill, main };
